  function modifiers(r2) {
    const m2 = { gather: { chop: 1, mine: 1, forage: 1 }, researchSlots: RESEARCH_QUEUE_BASE, researchSpeed: 1, carryBonus: 0, storage: 1, cropSpeed: 1, queueSlots: 0 };
    for (const id of r2.done) {
      for (const e2 of TOPIC_BY_ID[id]?.effects ?? []) {
        switch (e2.type) {
          case "gatherSpeed":
            m2.gather[e2.anim] *= e2.mult;
            break;
          case "researchSlots":
            m2.researchSlots += e2.add;
            break;
          case "researchSpeed":
            m2.researchSpeed *= e2.mult;
            break;
          case "carry":
            m2.carryBonus += e2.add;
            break;
          case "storage":
            m2.storage *= e2.mult;
            break;
          case "cropSpeed":
            m2.cropSpeed *= e2.mult;
            break;
          case "queueSlots":
            m2.queueSlots += e2.add;
            break;
          case "eraCapstone":
            break;
        }
      }
    }
    return m2;
  }
  function prereqsMet(r2, id, era = "neolithic") {
    const t2 = TOPIC_BY_ID[id];
    if (!t2) return { ok: false, reason: "Unknown topic" };
    if (t2.hidden && !(r2.revealed ?? []).includes(t2.id)) return { ok: false, reason: "Undiscovered" };
    if (!eraReached(era, t2.era)) return { ok: false, reason: `Opens in the ${ERA_NAMES[t2.era]} era` };
    const missing = t2.prereqs.filter((p2) => !r2.done.includes(p2) && !r2.queue.includes(p2));
    if (missing.length) return { ok: false, reason: `Needs ${missing.map((p2) => TOPIC_BY_ID[p2].name).join(", ")}` };
    if (t2.requiresCount) {
      const sameEra = (d2) => (TOPIC_BY_ID[d2]?.era ?? "neolithic") === (t2.era ?? "neolithic");
      const others = r2.done.filter((d2) => !t2.prereqs.includes(d2) && sameEra(d2)).length;
      if (others < t2.requiresCount) return { ok: false, reason: `Needs ${t2.requiresCount} other topics researched (${others} so far)` };
    }
    return { ok: true };
  }
  function canQueue(r2, id, era = "neolithic") {
    if (r2.done.includes(id)) return { ok: false, reason: "Already researched" };
    if (r2.queue.includes(id)) return { ok: false, reason: "Already queued" };
    const pre = prereqsMet(r2, id, era);
    if (!pre.ok) return pre;
    if (r2.queue.length >= modifiers(r2).researchSlots) return { ok: false, reason: "Research queue is full" };
    return { ok: true };
  }
  function queueResearch(r2, id, era = "neolithic") {
    const check = canQueue(r2, id, era);
    if (check.ok) r2.queue.push(id);
    return check;
  }
  function cancelResearch(r2, id) {
    if (!r2.queue.includes(id)) return;
    const drop = /* @__PURE__ */ new Set([id]);
    for (const q of r2.queue) if (TOPIC_BY_ID[q].prereqs.some((p2) => drop.has(p2))) drop.add(q);
    r2.queue = r2.queue.filter((q) => !drop.has(q));
  }
  function researchNext(r2, id) {
    const i2 = r2.queue.indexOf(id);
    if (i2 <= 0) return;
    if (!TOPIC_BY_ID[id].prereqs.every((p2) => r2.done.includes(p2))) return;
    r2.queue.splice(i2, 1);
    r2.queue.unshift(id);
  }
  function researchStation(s2) {
    let best = { buildingId: null, label: "camp", mult: 1 };
    for (const b2 of s2.buildings) {
      const st = RESEARCH_STATIONS[b2.def];
      if (b2.status === "done" && st && (best.buildingId === null || st.mult > best.mult)) best = { buildingId: b2.id, label: st.label, mult: st.mult };
    }
    return best;
  }

