  function stones(p2, x0, x1, y2) {
    for (let x2 = x0; x2 < x1; x2 += 5) {
      p2.ellipse(x2 + 2, y2, 3, 2.5, PAL.rockDark);
      p2.rect(x2 + 1, y2 - 2, 2, 1, PAL.rockLight);
    }
  }
  function roof(p2, x0, x1, base, peak, color, dark) {
    const mid = (x0 + x1) / 2;
    for (let y2 = peak; y2 <= base; y2++) {
      const half = (y2 - peak) / (base - peak) * (x1 - x0) / 2;
      p2.rect(mid - half, y2, half, 1, color);
      p2.rect(mid, y2, half, 1, dark);
      if ((y2 - peak) % 4 === 0) p2.rect(mid - half, y2, half * 2, 1, dark);
    }
  }
